import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 998244353;

    public static void main(String[] args) {
        new Main().process();
    }

    void process() {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);

        int n = in.readInt();
        int k = in.readInt();
        int[] poly = new int[10];
        for (int i = 0; i < k; i++) {
            poly[in.readInt()] = 1;
        }

        int[] res = new int[]{1};
        int exp = n / 2;

        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = multiply(res, poly, MOD);
            }
            poly = multiply(poly, poly, MOD);
            exp >>= 1;
        }

        long sum = 0;
        for (int c : res) {
            sum = (sum + (long)c * c) % MOD;
        }
        out.printLine(sum);
    }

    int[] multiply(int[] a, int[] b, int mod) {
        int required = a.length + b.length - 1;
        int size = 1;
        while (size < required) size <<= 1;

        double[] ra = new double[size];
        double[] ia = new double[size];
        double[] rb = new double[size];
        double[] ib = new double[size];

        for (int i = 0; i < a.length; i++) {
            long val = a[i] % mod;
            if (val < 0) val += mod;
            ra[i] = val & 0x7fff;
            ia[i] = val >>> 15;
        }

        for (int i = 0; i < b.length; i++) {
            long val = b[i] % mod;
            if (val < 0) val += mod;
            rb[i] = val & 0x7fff;
            ib[i] = val >>> 15;
        }

        fft(ra, ia, false);
        fft(rb, ib, false);

        double[] resR = new double[size];
        double[] resI = new double[size];

        for (int i = 0; i < size; i++) {
            int j = (size - i) & (size - 1);
            double a1r = (ra[i] + ra[j]) * 0.5;
            double a1i = (ia[i] - ia[j]) * 0.5;
            double a2r = (ia[i] + ia[j]) * 0.5;
            double a2i = (ra[j] - ra[i]) * 0.5;

            double b1r = (rb[i] + rb[j]) * 0.5;
            double b1i = (ib[i] - ib[j]) * 0.5;
            double b2r = (ib[i] + ib[j]) * 0.5;
            double b2i = (rb[j] - rb[i]) * 0.5;

            resR[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
            resI[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
        }

        fft(resR, resI, true);

        int[] result = new int[required];
        for (int i = 0; i < required; i++) {
            long val = Math.round(resR[i]);
            long val2 = Math.round(resI[i]);
            long combined = (val + (val2 << 15)) % mod;
            result[i] = (int) combined;
        }
        return result;
    }

    void fft(double[] re, double[] im, boolean inv) {
        int n = re.length;
        int bits = 31 - Integer.numberOfLeadingZeros(n - 1);
        for (int i = 1; i < n; i++) {
            int rev = Integer.reverse(i) >>> (32 - bits);
            if (i < rev) {
                double t = re[i]; re[i] = re[rev]; re[rev] = t;
                double t2 = im[i]; im[i] = im[rev]; im[rev] = t2;
            }
        }

        for (int len = 2; len <= n; len <<= 1) {
            int half = len >> 1;
            double ang = 2 * Math.PI / len * (inv ? -1 : 1);
            double wlenRe = Math.cos(ang);
            double wlenIm = Math.sin(ang);

            for (int i = 0; i < n; i += len) {
                double wRe = 1, wIm = 0;
                for (int j = 0; j < half; j++) {
                    double uRe = re[i + j], uIm = im[i + j];
                    double vRe = re[i + j + half] * wRe - im[i + j + half] * wIm;
                    double vIm = re[i + j + half] * wIm + im[i + j + half] * wRe;

                    re[i + j] = uRe + vRe;
                    im[i + j] = uIm + vIm;
                    re[i + j + half] = uRe - vRe;
                    im[i + j + half] = uIm - vIm;

                    double tmp = wRe * wlenRe - wIm * wlenIm;
                    wIm = wRe * wlenIm + wIm * wlenRe;
                    wRe = tmp;
                }
            }
        }

        if (inv) {
            for (int i = 0; i < n; i++) {
                re[i] /= n;
                im[i] /= n;
            }
        }
    }

    static class InputReader {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int idx, total;

        public InputReader(InputStream in) { this.in = in; }

        private int read() {
            if (total == -1) throw new RuntimeException();
            if (idx >= total) {
                idx = 0;
                try { total = in.read(buffer); } catch (IOException e) { throw new RuntimeException(); }
                if (total <= 0) return -1;
            }
            return buffer[idx++];
        }

        public int readInt() {
            int c = read();
            while (c <= ' ') c = read();
            int sign = 1;
            if (c == '-') { sign = -1; c = read(); }
            int num = 0;
            while (c > ' ') {
                if (c < '0' || c > '9') throw new NumberFormatException();
                num = num * 10 + c - '0';
                c = read();
            }
            return num * sign;
        }
    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream stream) {
            writer = new PrintWriter(stream);
        }

        public void printLine(Object o) {
            writer.println(o);
        }

        public void close() {
            writer.close();
        }
    }
}
